module gemm8x8x32_bias_relu_top #(
  parameter int M_MAX    = 8,
  parameter int N_MAX    = 8,
  parameter int K_MAX    = 32,
  parameter int A_ELEM_W = 8,
  parameter int ACC_W    = 32
)(
  input  logic                      clk,
  input  logic                      rst,
  input  logic                      s_valid,
  output logic                      s_ready,
  input  logic signed [31:0]        s_data,
  input  logic        [1:0]         s_type,
  output logic                      m_valid,
  input  logic                      m_ready,
  output logic signed [31:0]        m_data,
  output logic                      busy,
  output logic                      done,
  output logic                      error
);
  localparam int A_DEPTH = M_MAX*K_MAX;
  localparam int B_DEPTH = K_MAX*N_MAX;
  localparam int O_DEPTH = M_MAX*N_MAX;
  localparam int A_AW = (A_DEPTH > 1) ? $clog2(A_DEPTH) : 1;
  localparam int B_AW = (B_DEPTH > 1) ? $clog2(B_DEPTH) : 1;
  localparam int N_AW = (N_MAX   > 1) ? $clog2(N_MAX)   : 1;
  localparam int O_AW = (O_DEPTH > 1) ? $clog2(O_DEPTH) : 1;

  typedef enum logic [2:0] {
    ST_IDLE,
    ST_LOAD,
    ST_COMPUTE,
    ST_POST,
    ST_OUTPUT,
    ST_DONE
  } state_t;

  state_t state;

  logic start_load, start_compute, start_post, start_out;
  logic load_done, load_error;
  logic compute_done, acc_valid;
  logic [((M_MAX>1)?$clog2(M_MAX):1)-1:0] acc_m;
  logic [((N_MAX>1)?$clog2(N_MAX):1)-1:0] acc_n;
  logic signed [ACC_W-1:0] acc_data;
  logic post_done;
  logic out_done;

  logic a_wr_en, b_wr_en, bias_wr_en, out_wr_en;
  logic [A_AW-1:0] a_wr_addr, a_rd_addr;
  logic [B_AW-1:0] b_wr_addr, b_rd_addr;
  logic [N_AW-1:0] bias_wr_addr, bias_rd_addr;
  logic [O_AW-1:0] out_wr_addr, out_rd_addr;
  logic signed [A_ELEM_W-1:0] a_wr_data, b_wr_data, a_rd_data, b_rd_data;
  logic signed [ACC_W-1:0] bias_wr_data, bias_rd_data, out_wr_data, out_rd_data;

  logic sticky_error;
  logic cmd_hs_idle;

  assign cmd_hs_idle = (state == ST_IDLE) && !sticky_error && s_valid && s_ready && (s_type == 2'b00);

  always_ff @(posedge clk) begin
    if (rst) begin
      state <= ST_IDLE;
      sticky_error <= 1'b0;
      done <= 1'b0;
      start_load <= 1'b0;
      start_compute <= 1'b0;
      start_post <= 1'b0;
      start_out <= 1'b0;
    end else begin
      done <= 1'b0;
      start_load <= 1'b0;
      start_compute <= 1'b0;
      start_post <= 1'b0;
      start_out <= 1'b0;

      if (load_error) sticky_error <= 1'b1;

      case (state)
        ST_IDLE: begin
          if (cmd_hs_idle) begin
            start_load <= 1'b1;
            state <= ST_LOAD;
          end
        end
        ST_LOAD: begin
          if (load_done) begin
            start_compute <= 1'b1;
            start_post <= 1'b1;
            state <= ST_COMPUTE;
          end
        end
        ST_COMPUTE: begin
          if (compute_done) state <= ST_POST;
        end
        ST_POST: begin
          if (post_done) begin
            start_out <= 1'b1;
            state <= ST_OUTPUT;
          end
        end
        ST_OUTPUT: begin
          if (out_done) begin
            done <= 1'b1;
            state <= ST_DONE;
          end
        end
        ST_DONE: state <= ST_IDLE;
        default: state <= ST_IDLE;
      endcase
    end
  end

  input_loader #(.M_MAX(M_MAX),.N_MAX(N_MAX),.K_MAX(K_MAX),.A_ELEM_W(A_ELEM_W),.ACC_W(ACC_W)) u_loader (
    .clk(clk),.rst(rst),.start_load(start_load),.s_valid(s_valid),.s_ready(s_ready),.s_data(s_data),.s_type(s_type),
    .a_wr_en(a_wr_en),.a_wr_addr(a_wr_addr),.a_wr_data(a_wr_data),
    .b_wr_en(b_wr_en),.b_wr_addr(b_wr_addr),.b_wr_data(b_wr_data),
    .bias_wr_en(bias_wr_en),.bias_wr_addr(bias_wr_addr),.bias_wr_data(bias_wr_data),
    .load_done(load_done),.error_flag(load_error)
  );

  gemm_core_seq #(.M_MAX(M_MAX),.N_MAX(N_MAX),.K_MAX(K_MAX),.A_ELEM_W(A_ELEM_W),.ACC_W(ACC_W)) u_gemm (
    .clk(clk),.rst(rst),.start_compute(start_compute),
    .a_rd_addr(a_rd_addr),.a_rd_data(a_rd_data),.b_rd_addr(b_rd_addr),.b_rd_data(b_rd_data),
    .acc_valid(acc_valid),.acc_m(acc_m),.acc_n(acc_n),.acc_data(acc_data),.compute_done(compute_done)
  );

  postproc_relu_bias #(.M_MAX(M_MAX),.N_MAX(N_MAX),.ACC_W(ACC_W)) u_post (
    .clk(clk),.rst(rst),.start_post(start_post),.acc_valid(acc_valid),.acc_m(acc_m),.acc_n(acc_n),.acc_data(acc_data),
    .bias_rd_addr(bias_rd_addr),.bias_rd_data(bias_rd_data),
    .out_wr_en(out_wr_en),.out_wr_addr(out_wr_addr),.out_wr_data(out_wr_data),.post_done(post_done)
  );

  output_streamer #(.M_MAX(M_MAX),.N_MAX(N_MAX),.ACC_W(ACC_W)) u_out (
    .clk(clk),.rst(rst),.start_out(start_out),.out_rd_addr(out_rd_addr),.out_rd_data(out_rd_data),
    .m_valid(m_valid),.m_ready(m_ready),.m_data(m_data),.out_done(out_done)
  );

  local_memories #(.M_MAX(M_MAX),.N_MAX(N_MAX),.K_MAX(K_MAX),.A_ELEM_W(A_ELEM_W),.ACC_W(ACC_W)) u_mem (
    .clk(clk),
    .a_wr_en(a_wr_en),.a_wr_addr(a_wr_addr),.a_wr_data(a_wr_data),.a_rd_addr(a_rd_addr),.a_rd_data(a_rd_data),
    .b_wr_en(b_wr_en),.b_wr_addr(b_wr_addr),.b_wr_data(b_wr_data),.b_rd_addr(b_rd_addr),.b_rd_data(b_rd_data),
    .bias_wr_en(bias_wr_en),.bias_wr_addr(bias_wr_addr),.bias_wr_data(bias_wr_data),.bias_rd_addr(bias_rd_addr),.bias_rd_data(bias_rd_data),
    .out_wr_en(out_wr_en),.out_wr_addr(out_wr_addr),.out_wr_data(out_wr_data),.out_rd_addr(out_rd_addr),.out_rd_data(out_rd_data)
  );

  assign busy  = (state != ST_IDLE);
  assign error = sticky_error;
endmodule

module input_loader #(
  parameter int M_MAX=8, N_MAX=8, K_MAX=32, A_ELEM_W=8, ACC_W=32
)(
  input  logic clk,
  input  logic rst,
  input  logic start_load,
  input  logic s_valid,
  output logic s_ready,
  input  logic signed [31:0] s_data,
  input  logic [1:0] s_type,
  output logic a_wr_en,
  output logic [((M_MAX*K_MAX>1)?$clog2(M_MAX*K_MAX):1)-1:0] a_wr_addr,
  output logic signed [A_ELEM_W-1:0] a_wr_data,
  output logic b_wr_en,
  output logic [((K_MAX*N_MAX>1)?$clog2(K_MAX*N_MAX):1)-1:0] b_wr_addr,
  output logic signed [A_ELEM_W-1:0] b_wr_data,
  output logic bias_wr_en,
  output logic [((N_MAX>1)?$clog2(N_MAX):1)-1:0] bias_wr_addr,
  output logic signed [ACC_W-1:0] bias_wr_data,
  output logic load_done,
  output logic error_flag
);
  localparam int A_CNT_MAX = M_MAX*K_MAX;
  localparam int B_CNT_MAX = K_MAX*N_MAX;
  localparam int C_CNT_MAX = N_MAX;

  localparam int A_AW = ((M_MAX*K_MAX)>1)?$clog2(M_MAX*K_MAX):1;
  localparam int B_AW = ((K_MAX*N_MAX)>1)?$clog2(K_MAX*N_MAX):1;
  localparam int C_AW = ((N_MAX)>1)?$clog2(N_MAX):1;

  typedef enum logic [2:0] {L_IDLE,L_A,L_B,L_BIAS,L_DONE,L_ERR} lstate_t;
  lstate_t st;

  logic [A_AW-1:0] ca;
  logic [B_AW-1:0] cb;
  logic [C_AW-1:0] cc;

  always_ff @(posedge clk) begin
    if (rst) begin
      st <= L_IDLE;
      ca <= '0;
      cb <= '0;
      cc <= '0;
      load_done <= 1'b0;
      error_flag <= 1'b0;
      a_wr_en <= 1'b0;
      b_wr_en <= 1'b0;
      bias_wr_en <= 1'b0;
      a_wr_addr <= '0;
      b_wr_addr <= '0;
      bias_wr_addr <= '0;
      a_wr_data <= '0;
      b_wr_data <= '0;
      bias_wr_data <= '0;
    end else begin
      load_done <= 1'b0;
      a_wr_en <= 1'b0;
      b_wr_en <= 1'b0;
      bias_wr_en <= 1'b0;

      if (start_load) begin
        st <= L_A;
        ca <= '0;
        cb <= '0;
        cc <= '0;
      end else begin
        case (st)
          L_IDLE: begin end
          L_A: if (s_valid) begin
            if ((s_type!=2'b01) || (s_data[31:8]!=24'd0)) begin error_flag<=1'b1; st<=L_ERR; end
            else begin
              a_wr_en <= 1'b1;
              a_wr_addr <= ca;
              a_wr_data <= s_data[A_ELEM_W-1:0];
              if (ca == A_CNT_MAX-1) st <= L_B;
              else ca <= ca + 1'b1;
            end
          end
          L_B: if (s_valid) begin
            if ((s_type!=2'b10) || (s_data[31:8]!=24'd0)) begin error_flag<=1'b1; st<=L_ERR; end
            else begin
              b_wr_en <= 1'b1;
              b_wr_addr <= cb;
              b_wr_data <= s_data[A_ELEM_W-1:0];
              if (cb == B_CNT_MAX-1) st <= L_BIAS;
              else cb <= cb + 1'b1;
            end
          end
          L_BIAS: if (s_valid) begin
            if (s_type!=2'b11) begin error_flag<=1'b1; st<=L_ERR; end
            else begin
              bias_wr_en <= 1'b1;
              bias_wr_addr <= cc;
              bias_wr_data <= s_data;
              if (cc == C_CNT_MAX-1) begin st<=L_DONE; load_done<=1'b1; end
              else cc <= cc + 1'b1;
            end
          end
          L_DONE: st <= L_IDLE;
          L_ERR: st <= L_ERR;
          default: st <= L_IDLE;
        endcase
      end
    end
  end

  assign s_ready = (st==L_A)||(st==L_B)||(st==L_BIAS);
endmodule

module gemm_core_seq #(
  parameter int M_MAX=8, N_MAX=8, K_MAX=32, A_ELEM_W=8, ACC_W=32
)(
  input logic clk,
  input logic rst,
  input logic start_compute,
  output logic [((M_MAX*K_MAX>1)?$clog2(M_MAX*K_MAX):1)-1:0] a_rd_addr,
  input  logic signed [A_ELEM_W-1:0] a_rd_data,
  output logic [((K_MAX*N_MAX>1)?$clog2(K_MAX*N_MAX):1)-1:0] b_rd_addr,
  input  logic signed [A_ELEM_W-1:0] b_rd_data,
  output logic acc_valid,
  output logic [((M_MAX>1)?$clog2(M_MAX):1)-1:0] acc_m,
  output logic [((N_MAX>1)?$clog2(N_MAX):1)-1:0] acc_n,
  output logic signed [ACC_W-1:0] acc_data,
  output logic compute_done
);
  localparam int M_W = (M_MAX>1)?$clog2(M_MAX):1;
  localparam int N_W = (N_MAX>1)?$clog2(N_MAX):1;
  localparam int K_W = (K_MAX>1)?$clog2(K_MAX):1;

  logic run;
  logic [M_W-1:0] m;
  logic [N_W-1:0] n;
  logic [K_W-1:0] k_issue;
  logic [K_W-1:0] k_resp;
  logic signed [ACC_W-1:0] acc;
  logic req_valid;
  logic resp_valid;
  logic signed [15:0] prod16;
  logic signed [ACC_W-1:0] prod32;
  logic signed [ACC_W-1:0] sum32;

  always_ff @(posedge clk) begin
    if(rst) begin
      run <= 1'b0;
      m <= '0;
      n <= '0;
      k_issue <= '0;
      k_resp <= '0;
      acc <= '0;
      req_valid <= 1'b0;
      resp_valid <= 1'b0;
      acc_valid <= 1'b0;
      acc_m <= '0;
      acc_n <= '0;
      acc_data <= '0;
      compute_done <= 1'b0;
      a_rd_addr <= '0;
      b_rd_addr <= '0;
    end else begin
      acc_valid <= 1'b0;
      compute_done <= 1'b0;

      resp_valid <= req_valid;
      k_resp <= k_issue;

      if (start_compute) begin
        run <= 1'b1;
        m <= '0;
        n <= '0;
        k_issue <= '0;
        acc <= '0;
        req_valid <= 1'b1;
        a_rd_addr <= '0;
        b_rd_addr <= '0;
      end else if (run) begin
        if (req_valid) begin
          a_rd_addr <= m*K_MAX + k_issue;
          b_rd_addr <= k_issue*N_MAX + n;
          if (k_issue == K_MAX-1) req_valid <= 1'b0;
          else k_issue <= k_issue + 1'b1;
        end

        if (resp_valid) begin
          prod16 = a_rd_data * b_rd_data;
          prod32 = $signed({{(ACC_W-16){prod16[15]}}, prod16});
          sum32 = acc + prod32;

          if (k_resp == K_MAX-1) begin
            acc_valid <= 1'b1;
            acc_m <= m;
            acc_n <= n;
            acc_data <= sum32;
            acc <= '0;

            if ((m == M_MAX-1) && (n == N_MAX-1)) begin
              run <= 1'b0;
              compute_done <= 1'b1;
              req_valid <= 1'b0;
            end else begin
              if (n == N_MAX-1) begin n <= '0; m <= m + 1'b1; end
              else n <= n + 1'b1;
              k_issue <= '0;
              req_valid <= 1'b1;
            end
          end else begin
            acc <= sum32;
          end
        end
      end else begin
        req_valid <= 1'b0;
      end
    end
  end
endmodule

module postproc_relu_bias #(
  parameter int M_MAX=8, N_MAX=8, ACC_W=32
)(
  input logic clk,
  input logic rst,
  input logic start_post,
  input logic acc_valid,
  input logic [((M_MAX>1)?$clog2(M_MAX):1)-1:0] acc_m,
  input logic [((N_MAX>1)?$clog2(N_MAX):1)-1:0] acc_n,
  input logic signed [ACC_W-1:0] acc_data,
  output logic [((N_MAX>1)?$clog2(N_MAX):1)-1:0] bias_rd_addr,
  input  logic signed [ACC_W-1:0] bias_rd_data,
  output logic out_wr_en,
  output logic [((M_MAX*N_MAX>1)?$clog2(M_MAX*N_MAX):1)-1:0] out_wr_addr,
  output logic signed [ACC_W-1:0] out_wr_data,
  output logic post_done
);
  localparam int M_W = (M_MAX>1)?$clog2(M_MAX):1;
  localparam int N_W = (N_MAX>1)?$clog2(N_MAX):1;

  logic active;
  logic pend;
  logic [M_W-1:0] pm;
  logic [N_W-1:0] pn;
  logic signed [ACC_W-1:0] pdata;
  logic signed [ACC_W-1:0] sum;

  always_ff @(posedge clk) begin
    if(rst) begin
      active <= 1'b0;
      pend <= 1'b0;
      out_wr_en <= 1'b0;
      out_wr_addr <= '0;
      out_wr_data <= '0;
      bias_rd_addr <= '0;
      pm <= '0;
      pn <= '0;
      pdata <= '0;
      post_done <= 1'b0;
    end else begin
      out_wr_en <= 1'b0;
      post_done <= 1'b0;

      if (start_post) active <= 1'b1;

      if (active && acc_valid && !pend) begin
        bias_rd_addr <= acc_n;
        pm <= acc_m;
        pn <= acc_n;
        pdata <= acc_data;
        pend <= 1'b1;
      end

      if (pend) begin
        sum = pdata + bias_rd_data;
        out_wr_en <= 1'b1;
        out_wr_addr <= pm*N_MAX + pn;
        out_wr_data <= sum[ACC_W-1] ? '0 : sum;
        if ((pm == M_MAX-1) && (pn == N_MAX-1)) begin
          post_done <= 1'b1;
          active <= 1'b0;
        end
        pend <= 1'b0;
      end
    end
  end
endmodule

module output_streamer #(
  parameter int M_MAX=8, N_MAX=8, ACC_W=32
)(
  input logic clk,
  input logic rst,
  input logic start_out,
  output logic [((M_MAX*N_MAX>1)?$clog2(M_MAX*N_MAX):1)-1:0] out_rd_addr,
  input  logic signed [ACC_W-1:0] out_rd_data,
  output logic m_valid,
  input  logic m_ready,
  output logic signed [ACC_W-1:0] m_data,
  output logic out_done
);
  localparam int O_DEPTH = M_MAX*N_MAX;
  localparam int O_W = (O_DEPTH>1)?$clog2(O_DEPTH):1;

  logic active;
  logic [O_W-1:0] rd_issue_idx;
  logic [O_W-1:0] sent_cnt;
  logic pending_data;

  always_ff @(posedge clk) begin
    if(rst) begin
      active <= 1'b0;
      rd_issue_idx <= '0;
      sent_cnt <= '0;
      pending_data <= 1'b0;
      out_rd_addr <= '0;
      m_valid <= 1'b0;
      m_data <= '0;
      out_done <= 1'b0;
    end else begin
      out_done <= 1'b0;

      if (start_out) begin
        active <= 1'b1;
        rd_issue_idx <= '0;
        sent_cnt <= '0;
        pending_data <= 1'b1;
        out_rd_addr <= '0;
        m_valid <= 1'b0;
      end else begin
        if (pending_data) begin
          m_data <= out_rd_data;
          m_valid <= 1'b1;
          pending_data <= 1'b0;
        end

        if (active && m_valid && m_ready) begin
          if (sent_cnt == O_DEPTH-1) begin
            out_done <= 1'b1;
            active <= 1'b0;
            m_valid <= 1'b0;
          end else begin
            sent_cnt <= sent_cnt + 1'b1;
            rd_issue_idx <= rd_issue_idx + 1'b1;
            out_rd_addr <= rd_issue_idx + 1'b1;
            m_valid <= 1'b0;
            pending_data <= 1'b1;
          end
        end
      end
    end
  end
endmodule
